   144	    private OrderSpecifier<?> getOrderByClause(
   145	            SortOption sortOption,
   146	            QProduct product,
   147	            QProductColor productColor,
   148	            QProductSize productSize) {
   149	        log.debug("정렬 조건 설정 - 정렬 옵션: {}", sortOption);
   150	
   151	        String field = sortOption != null ? sortOption.getField() : null;
   152	        String order = sortOption != null ? sortOption.getOrder() : null;
   153	
   154	        if (field == null || order == null) {
   155	            log.debug("기본 정렬 적용 - 상품ID 오름차순");
   156	            return product.id.asc(); // 기본 정렬
   157	        }
   158	
   159	        if (sortOption != null) {
   160	            log.debug("정렬 옵션 적용 - 필드: {}, 순서: {}", field, order);
   161	            switch (sortOption.getField()) {
   162	                case "price":
   163	                    return "asc".equalsIgnoreCase(sortOption.getOrder())
   164	                            ? productSize.purchasePrice.asc()
   165	                            : productSize.purchasePrice.desc();
   166	                case "releaseDate":
   167	                    return "asc".equalsIgnoreCase(sortOption.getOrder())
   168	                            ? product.releaseDate.asc()
   169	                            : product.releaseDate.desc();
   170	                case "interestCount":
   171	                    return "asc".equalsIgnoreCase(sortOption.getOrder())
   172	                            ? productColor.interests.size().sum().asc()
   173	                            : productColor.interests.size().sum().desc();
   174	                default:
   175	                    log.debug("알 수 없는 정렬 필드 - 기본 정렬 적용: {}", field);
   176	                    break;
   177	            }
   178	        }
   179	        return product.id.asc(); // 기본 정렬
   180	    }
