   149	    QStyle style = QStyle.style;
   150	    QProfile profile = QProfile.profile;
   151	    QStyleOrderItem styleOrderItem = QStyleOrderItem.styleOrderItem;
   152	    QOrderItem orderItem = QOrderItem.orderItem;
   153	    QMediaUrl mediaUrl = QMediaUrl.mediaUrl;
   154	    QProductSize productSize = QProductSize.productSize;
   155	    QProductColor productColor = QProductColor.productColor;
   156	    QProduct product = QProduct.product;
   157	    QBrand brand = QBrand.brand;
   158	
   159	    // 1단계: 필터링 조건에 맞는 스타일 ID 찾기
   160	    BooleanBuilder filterBuilder = new BooleanBuilder();
   161	
   162	    if (filterRequestDto != null) {
   163	        if (filterRequestDto.getBrandName() != null) {
   164	            filterBuilder.and(brand.name.eq(filterRequestDto.getBrandName()));
   165	        }
   166	        if (filterRequestDto.getCollectionName() != null) {
   167	            filterBuilder.and(product.collection.name.eq(filterRequestDto.getCollectionName()));
   168	        }
   169	        if (filterRequestDto.getCategoryId() != null) {
   170	            filterBuilder.and(product.category.id.eq(filterRequestDto.getCategoryId()));
   171	        }
   172	        if (filterRequestDto.getProfileName() != null) {
   173	            filterBuilder.and(profile.profileName.eq(filterRequestDto.getProfileName()));
   174	        }
   175	    }
   176	
   177	    List<Long> filteredStyleIds = queryFactory
   178	            .select(style.id)
   179	            .from(style)
   180	            .leftJoin(style.profile, profile)
   181	            .leftJoin(style.styleOrderItems, styleOrderItem)
   182	            .leftJoin(styleOrderItem.orderItem, orderItem)
   183	            .leftJoin(orderItem.productSize, productSize)
   184	            .leftJoin(productSize.productColor, productColor)
   185	            .leftJoin(productColor.product, product)
   186	            .leftJoin(product.brand, brand)
   187	            .where(filterBuilder)
   188	            .distinct()
   189	            .fetch();
   190	
