   209	                                    ))),
   210	                    style.viewCount,
   211	                    style.likes.size() // 좋아요 수 계산
   212	            ))
   213	            .from(style)
   214	            .leftJoin(style.profile, profile)
   215	            .where(style.id.in(filteredStyleIds))
   216	            .offset(pageable.getOffset())
   217	            .limit(pageable.getPageSize());
   218	
   219	    // 정렬
   220	    if (filterRequestDto != null && "popular".equals(filterRequestDto.getSortBy())) {
   221	        query.orderBy(style.viewCount.desc(), style.id.desc());
   222	    } else {
